function bt_psd_mc_config(this_block)
% Black Box configuration of 'bt_psd_mc' for Model Composer / System Generator.
% Generated by python/scripts/gen_mc.py from modelcomposer/hdl/bt_psd_mc.v; do not edit, regenerate instead.
% Configuration: WL = 12, NCHUNKS = 5, ROUND = 1, SQ_SERIAL = 1.
% Not executed in the environment this repository was developed in (no MATLAB there): see docs/MODEL_COMPOSER.md.

  this_block.setTopLevelLanguage('Verilog');
  this_block.setEntityName('bt_psd_mc');

  % Registered paths (the read data follows rd_addr one clock later): do not tag the block as combinational.
  this_block.addSimulinkInport('rst');
  this_block.addSimulinkInport('in_valid');
  this_block.addSimulinkInport('in_data');
  this_block.addSimulinkInport('rd_addr');

  this_block.addSimulinkOutport('busy');
  this_block.addSimulinkOutport('done');
  this_block.addSimulinkOutport('rd_data');

  busy_port = this_block.port('busy');
  busy_port.setType('UFix_1_0');
  busy_port.useHDLVector(false);
  done_port = this_block.port('done');
  done_port.setType('UFix_1_0');
  done_port.useHDLVector(false);
  rd_data_port = this_block.port('rd_data');
  rd_data_port.setType('UFix_32_0');
  rd_data_port.useHDLVector(true);

  % -----------------------------
  if (this_block.inputTypesKnown)
    % the widths the HDL was written for (gateways: Fix_12_11 for in_data, UFix_10_0 for rd_addr, Boolean for the rest)
    if (this_block.port('rst').width ~= 1)
      this_block.setError('Input data type for port "rst" must have width=1.');
    end
    this_block.port('rst').useHDLVector(false);
    if (this_block.port('in_valid').width ~= 1)
      this_block.setError('Input data type for port "in_valid" must have width=1.');
    end
    this_block.port('in_valid').useHDLVector(false);
    if (this_block.port('in_data').width ~= 12)
      this_block.setError('Input data type for port "in_data" must have width=12.');
    end
    this_block.port('in_data').useHDLVector(true);
    if (this_block.port('rd_addr').width ~= 10)
      this_block.setError('Input data type for port "rd_addr" must have width=10.');
    end
    this_block.port('rd_addr').useHDLVector(true);
  end  % if(inputTypesKnown)
  % -----------------------------

  % -----------------------------
  if (this_block.inputRatesKnown)
    setup_as_single_rate(this_block,'clk','ce')
  end  % if(inputRatesKnown)
  % -----------------------------

  % The bundle holds every module the block needs; it is compiled as one file.
  here = fileparts(mfilename('fullpath'));
  this_block.addFile(fullfile(here, '..', 'hdl', 'bt_psd_mc_bundle.v'));
return;

% ------------------------------------------------------------
function setup_as_single_rate(block,clkname,cename)
  inputRates = block.inputRates;
  uniqueInputRates = unique(inputRates);
  if (length(uniqueInputRates)==1 && uniqueInputRates(1)==Inf)
    block.addError('The inputs to this block cannot all be constant.');
    return;
  end
  if (uniqueInputRates(end) == Inf)
     uniqueInputRates = uniqueInputRates(1:end-1);
  end
  if (length(uniqueInputRates) ~= 1)
    block.addError('The inputs to this block must run at a single rate.');
    return;
  end
  theInputRate = uniqueInputRates(1);
  for i = 1:block.numSimulinkOutports
     block.outport(i).setRate(theInputRate);
  end
  block.addClkCEPair(clkname,cename,theInputRate);
return;
